    companyname character varying(255) COLLATE pg_catalog."default" NOT NULL,
    createddate timestamp(6) without time zone,
    emailid character varying(255) COLLATE pg_catalog."default" NOT NULL,
    isactive boolean NOT NULL,
    phoneno bigint NOT NULL,
    registrationid character varying(255) COLLATE pg_catalog."default",
    CONSTRAINT vendor_pkey PRIMARY KEY (vendorid),
    CONSTRAINT ukai497u87sxgg9h3i37ylnllp9 UNIQUE (emailid),
